button {
  color: rgb(253, 119, 119);
  position: relative;
  overflow: hidden;
  outline: none;
  cursor: pointer;
  border-radius: 50px;
  background-color: hsl(118, 94%, 32%);
  border: solid 4px hsl(0, 0%, 100%);
  font-family: inherit;
}

.default-btn,
.hover-btn {
  background-color: hsl(118, 94%, 32%);
  display: -webkit-box;
  display: -moz-box;
  display: -ms-flexbox;
  display: -webkit-flex;
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 15px 20px;
  border-radius: 50px;
  font-size: 17px;
  font-weight: 500;
  text-transform: uppercase;
  transition: all 0.6s ease;
}

.hover-btn {
  position: absolute;
  inset: 0;
  background-color: hsl(0, 0%, 0%);
  transform: translate(0%, 100%);
}

.default-btn span {
  color: hsl(0, 0%, 100%);
}

.hover-btn span {
  color: hsl(0, 0%, 100%);
}

button:hover .default-btn {
  transform: translate(0%, -100%);
}

button:hover .hover-btn {
  transform: translate(0%, 0%);
}
